led4 = sg.load('/x'); sg.update(led4, 'options', [short], {}, {'CCC': bars([[101, 102, 99, 100]], '2026-10-22 09:55')}, now)
sg.update(led4, 'options', [], {}, {'CCC': bars([[100, 100, 84, 86], [86, 87, 69, 70]], '2026-10-22 10:00')}, T('2026-10-22 10:10'))
check('short (PUT) side: targets below, final target closes it with the right R', led4['signals'][0]['outcome'] == 'TARGET' and abs(led4['signals'][0]['r_final'] - (0.5 * 1.5 + 0.25 * 2 + 0.25 * 3)) < .01, str(led4['signals'][0].get('r_final')))
watch = dict(it, symbol='DDD', status='WATCH (in zone)', options_trade=None, label='LONG')
led5 = sg.load('/x'); sg.update(led5, 'intraday', [watch], {}, {}, now)
check('a setup in WATCH is remembered', len(led5['watch']) == 1 and not led5['signals'])
sg.update(led5, 'intraday', [], {('DDD', 'long'): 'BROKEN'}, {}, T('2026-10-22 10:05'))
check('when it disappears, it is listed as invalidated with the reason', len(led5['dropped']) == 1 and 'Zone broken' in led5['dropped'][0]['reason'] and not led5['watch'])
led6 = sg.load('/x'); sg.update(led6, 'intraday', [watch], {}, {}, now); sg.update(led6, 'intraday', [], {}, {}, T('2026-10-22 10:05'))
check('a symbol that was not scanned this run (data missing) is not wrongly invalidated', len(led6['dropped']) == 0)
led7 = sg.load('/x'); sg.update(led7, 'options', [it], {}, {}, now, can_open=False)
check('no new signals outside market hours (can_open=False)', not led7['signals'])
led8 = sg.load('/x'); sg.update(led8, 'options', [it], {}, {}, now); sg.update(led8, 'options', [it], {}, {}, T('2026-10-22 10:05'))
check('the same trigger is not opened twice', len(led8['signals']) == 1)
led9 = sg.load('/x'); sg.update(led9, 'intraday', [dict(it, symbol='LATE', label='LONG', options_trade=None)], {}, {'LATE': bars([[99, 101, 98, 100]], '2026-10-22 15:05')}, T('2026-10-22 15:11'))
check('no new intraday or options trade from a candle at or after 15:00', not led9['signals'])
led10 = sg.load('/x'); led10['signals'].append(dict(sg.new_signal('intraday', dict(it, symbol='OLD', label='LONG'), T('2026-10-22 15:10')), section='intraday'))
sg.update(led10, 'intraday', [], {}, {}, T('2026-10-22 15:20'))
check('late signals opened by the old version are cleaned out', not led10['signals'])
led11 = sg.load('/x'); sw = dict(it, symbol='SWG', label='LONG', options_trade=None)
sg.update(led11, 'swing', [sw], {}, {'SWG': bars([[99, 101, 98, 100]], '2026-10-22 10:15', 'h')}, T('2026-10-22 11:00'))
sg.update(led11, 'swing', [], {}, {'SWG': bars([[100, 116, 99, 114]], '2026-10-22 11:15', 'h')}, T('2026-10-22 12:00'))
s11 = led11['signals'][0]; check('swing: at T1 the stop stays where it was (no early breakeven)', s11['stop'] == 90.0 and 'T1' in s11['hits'], str(s11['stop']))
sg.update(led11, 'swing', [], {}, {'SWG': bars([[114, 121, 113, 119]], '2026-10-22 12:15', 'h')}, T('2026-10-22 13:00'))
check('swing: at T2 the stop moves to entry', s11['stop'] == 100.0)
import tempfile, os
p = os.path.join(tempfile.mkdtemp(), 'signals_options.json'); sg.save(p, led8, now); back = sg.load(p)
check('saved and loaded back intact', back['signals'][0]['id'] == led8['signals'][0]['id'] and 'updated' in back)
# ---- watch / dropped hygiene: a traded setup is never watched or dropped, flickers are one entry
def mkit(sym, status, bos='2026-11-10 10:00', **kw): return dict(it, symbol=sym, bos_date=bos, status=status, label='LONG', options_trade=None, **kw)
T0 = T('2026-11-10 10:00'); lg = sg.load('/x'); a1 = mkit('ZZA', 'TRIGGERED'); k1 = sg.key('intraday', a1)
sg.update(lg, 'intraday', [a1], {}, {'ZZA': bars([[99, 101, 98, 100]], '2026-11-10 10:00')}, T0)
check('trade created: it is a signal and not in the watch list', len(lg['signals']) == 1 and k1 not in lg['watch'])
sg.update(lg, 'intraday', [mkit('ZZA', 'WATCH (in zone)')], {}, {'ZZA': bars([[100, 101, 99, 100]], '2026-11-10 10:05')}, T('2026-11-10 10:05'))
check('the trigger candle passes and the setup shows "WATCH (in zone)" again: it does NOT come back into the watch list (it is a trade)', k1 not in lg['watch'], str(list(lg['watch'])))
lg['watch'][k1] = dict(id=k1, symbol='ZZA', status='WATCH (in zone)', first_seen='2026-11-10T10:00+05:30', last_seen='2026-11-10T10:05+05:30'); lg['dropped'].append(dict(id=k1, symbol='ZZA', first_seen='x', dropped='2026-11-10T09:00+05:30', reason='old', state='FAR'))
sg.update(lg, 'intraday', [], {}, {'ZZA': bars([[100, 101, 99, 100]], '2026-11-10 10:10')}, T('2026-11-10 10:10'))
check('an old file with a traded setup in the watch and dropped lists is healed on the next run', k1 not in lg['watch'] and not [d for d in lg['dropped'] if d['id'] == k1])
lf = sg.load('/x'); f1 = mkit('FLK', 'WATCH (in zone)'); kf = sg.key('intraday', f1)
for n, (items, st) in enumerate([([f1], None), ([], 'EXTENDED'), ([f1], None), ([], 'FAR'), ([f1], None), ([], 'EXTENDED')]):
    sg.update(lf, 'intraday', items, {('FLK', 'long'): st} if not items else {}, {}, T(f'2026-11-10 11:{n * 5:02d}'))
dd = [d for d in lf['dropped'] if d['id'] == kf]
check('a setup that flickers in and out three times ends as ONE dropped entry (the latest reason), never a pile of duplicates', len(dd) == 1 and dd[0]['state'] == 'EXTENDED' and kf not in lf['watch'], str(dd))
lb = sg.load('/x'); b1 = mkit('BCK', 'WATCH (in zone)'); kb = sg.key('intraday', b1)
sg.update(lb, 'intraday', [b1], {}, {}, T('2026-11-10 11:00')); sg.update(lb, 'intraday', [], {('BCK', 'long'): 'FAR'}, {}, T('2026-11-10 11:05'))
check('dropped: the setup is in the dropped list', [d['id'] for d in lb['dropped']] == [kb])
sg.update(lb, 'intraday', [b1], {}, {}, T('2026-11-10 11:10'))
check('back in play: a dropped setup that returns leaves the dropped list (never in two lists)', kb in lb['watch'] and not lb['dropped'])
sg.update(lb, 'intraday', [], {('BCK', 'long'): 'FAR'}, {}, T('2026-11-10 11:15')); sg.update(lb, 'intraday', [dict(b1, status='TRIGGERED')], {}, {'BCK': bars([[99, 101, 98, 100]], '2026-11-10 11:20')}, T('2026-11-10 11:20'))
check('dropped, then triggers later: it is a trade and the earlier drop is gone', len(lb['signals']) == 1 and not lb['dropped'] and kb not in lb['watch'])
lh = sg.load('/x')
for i, t_ in enumerate(['2026-11-10T10:00', '2026-11-10T11:00', '2026-11-10T12:00']): lh['dropped'].append(dict(id='intraday|DUP|long|x', symbol='DUP', first_seen=t_, dropped=t_ + '+05:30', reason='r', state='FAR'))
lh['dropped'].append(dict(id='intraday|ONE|long|y', symbol='ONE', first_seen='t', dropped='2026-11-10T09:00+05:30', reason='r', state='FAR'))
sg.update(lh, 'intraday', [], {}, {}, T('2026-11-10 12:30'))
check('an old file with the same setup dropped several times is cleaned to one entry (the latest)', [d['dropped'] for d in lh['dropped'] if d['id'] == 'intraday|DUP|long|x'] == ['2026-11-10T12:00+05:30'] and len(lh['dropped']) == 2)
# ---- 17 Nov 2026
sw = dict(it, symbol='SWG', label='LONG', options_trade=None, entry=100.0, sl=90.0, t1=110.0, t2=120.0, t3=130.0, bos_date='2026-10-01')
L = sg.load('/x'); sg.update(L, 'swing', [sw], {}, {'SWG': bars([[99, 101, 98, 100]], '2026-10-01 14:15', '1h')}, T('2026-10-01 15:00'))
days = [[100, 121, 99, 119], [119, 122, 112, 118], [118, 119, 108, 110], [110, 123, 114, 122], [122, 126, 118, 125], [125, 125.5, 104, 105]]   # T1+T2 on day 1; day 3's low 108 is a daily higher low once day 4 closes; day 6 falls through it
rows = []; idx = []
for n, (o, h, l, c) in enumerate(days):
    d = pd.Timestamp('2026-10-02', tz=TZ) + pd.Timedelta(days=n); rows += [[o, h, l, c]]; idx.append(d + pd.Timedelta(hours=10))
b = pd.DataFrame(rows, columns=['Open', 'High', 'Low', 'Close'], index=pd.DatetimeIndex(idx))
ev = sg.update(L, 'swing', [], {}, {'SWG': b}, T('2026-10-08 15:00')); s5 = L['signals'][0]
check('swing after T2: the stop is trailed below each new confirmed daily higher low (it used to stay at entry)', any(e['kind'] == 'trail' and 'trailed' in e['text'] for e in ev) and s5['stop'] > 100.0, f"stop {s5['stop']} {[e['text'] for e in ev]}")
check('...and the trailed stop closes the trade above entry instead of at breakeven', s5['status'] == 'CLOSED' and s5['outcome'] == 'TRAIL' and s5['r_final'] > 0.5 * 1 + 0.25 * 2, f"{s5['status']} {s5.get('r_final')}")
check('the daily higher low needs a finished day on each side and must be after the trigger day', sg.trail_level([(pd.Timestamp('2026-10-02').date(), 10, 20), (pd.Timestamp('2026-10-03').date(), 8, 20), (pd.Timestamp('2026-10-04').date(), 9, 20)], pd.Timestamp('2026-10-05').date(), pd.Timestamp('2026-10-01').date()) == 8.0 and sg.trail_level([(pd.Timestamp('2026-10-02').date(), 10, 20), (pd.Timestamp('2026-10-03').date(), 8, 20)], pd.Timestamp('2026-10-05').date(), pd.Timestamp('2026-10-01').date()) is None)
L2 = sg.load('/x'); a1 = dict(it, symbol='DUP', label='LONG', options_trade=None, bos_date='2026-10-22 09:30')
sg.update(L2, 'intraday', [a1], {}, {'DUP': bars([[99, 101, 98, 100]], '2026-10-22 09:55')}, now)
a2 = dict(a1, bos_date='2026-10-22 10:20', entry=101.0)
sg.update(L2, 'intraday', [a2], {}, {'DUP': bars([[100, 102, 99, 101]], '2026-10-22 10:25')}, T('2026-10-22 10:30'))
check('no second tracked trade on a stock while one is still open (same side)', len(L2['signals']) == 1, str([x['id'] for x in L2['signals']]))
sg.update(L2, 'intraday', [], {}, {'DUP': bars([[100, 100, 89, 90]], '2026-10-22 10:35')}, T('2026-10-22 10:40'))
a3 = dict(a1, bos_date='2026-10-22 10:45')
sg.update(L2, 'intraday', [a3], {}, {'DUP': bars([[95, 96, 94, 95]], '2026-10-22 10:50')}, T('2026-10-22 10:55'))
check('...once that trade has closed, a new trigger on the same stock is tracked again', len(L2['signals']) == 2 and L2['signals'][1]['status'] == 'ACTIVE')
L3 = sg.load('/x'); sg.update(L3, 'swing', [dict(sw, symbol='RNK', status='SET ALERT (wait for pullback)')], {}, {}, now)
sg.update(L3, 'swing', [], {('RNK', 'long'): 'OK'}, {}, T('2026-10-22 11:00'))
check('a setup that is still valid but only ranked out is not lost silently, and is not given the wrong reason ("structure no longer there")', len(L3['dropped']) == 1 and L3['dropped'][0]['state'] == 'MOVED' and 'still valid' in L3['dropped'][0]['reason'] and 'no longer there' not in L3['dropped'][0]['reason'] and not L3['watch'])
L4 = sg.load('/x'); sg.update(L4, 'swing', [dict(sw, symbol='MOV', stage=4, status='1H CONFIRMED (wait for 15m)', holds=['room < 2R'])], {}, {}, now)
sg.update(L4, 'swing', [dict(sw, symbol='MOV', stage=3, status='IN ZONE (wait for 1H)', holds=[])], {}, {}, T('2026-10-22 11:00'))
tr = L4['watch'][[k for k in L4['watch']][0]].get('trail', [])
check('a setup that moves from 1H confirmed (held back) to In zone keeps a trail of both steps', [x['stage'] for x in tr] == [4, 3] and tr[0]['held'] == 1 and tr[1]['held'] == 0, str(tr))
sg.update(L4, 'swing', [dict(sw, symbol='MOV', stage=3, status='IN ZONE (wait for 1H)', holds=[])], {}, {}, T('2026-10-22 11:05'))
check('an unchanged setup does not add trail rows every scan', len(L4['watch'][[k for k in L4['watch']][0]]['trail']) == 2)
sg.update(L3, 'swing', [dict(sw, symbol='WKL', status='SET ALERT (wait for pullback)')], {}, {}, now); sg.update(L3, 'swing', [], {('WKL', 'long'): 'WEEKLY'}, {}, T('2026-10-22 11:05'))
check('weekly trend turning down gives its own reason', L3['dropped'] and 'weekly' in L3['dropped'][-1]['reason'].lower(), str(L3['dropped']))
print('\nALL PASSED' if not fails else f'\n{len(fails)} FAILED: {fails}'); sys.exit(1 if fails else 0)
